public boolean mouseClicked(double x, double y, int btn) {
        for (int i = 0; i < textFields.size(); i++) {
            if (textFields.get(i).mouseClicked(x, y, btn)) {
                focus(i);
                return true;
            }
        }
        focus(-1);
