static void addProbeInfo(ProbeMode mode, IProbeInfo probeInfo, Player player, Level world, BlockState blockState, IProbeHitData data) {
        world.getBlockEntity(data.getPos(), ModBlockEntities.MODULAR_ROUTER.get()).ifPresent(router -> {
            if (router.isPermitted(player)) {
                IItemHandler modules = router.getModules();
                IProbeInfo sub = probeInfo.horizontal();
                for (int i = 0; i < modules.getSlots(); i++) {
                    ItemStack stack = modules.getStackInSlot(i);
                    if (!stack.isEmpty()) {
                        sub.element(new ElementModule(stack));
                    }
                }
                sub = probeInfo.horizontal();
                IItemHandler upgrades = router.getUpgrades();
                for (int i = 0; i < upgrades.getSlots(); i++) {
                    ItemStack stack = upgrades.getStackInSlot(i);
                    if (!stack.isEmpty()) {
                        sub.item(stack);
                    }
                }

                probeInfo.text(Component.literal(ChatFormatting.YELLOW.toString())
                        .append(Component.translatable("modularrouters.guiText.tooltip.redstone.label"))
                        .append(ChatFormatting.WHITE + ": ")
                        .append(Component.translatable(router.getRedstoneBehaviour().getTranslationKey()))
                );
            } else {
                probeInfo.text(Component.translatable("modularrouters.chatText.security.accessDenied"));
            }
        });
    }

@Override
    public void appendTooltip(ITooltip iTooltip, BlockAccessor blockAccessor, IPluginConfig iPluginConfig) {
        CompoundTag data = blockAccessor.getServerData();
        if (blockAccessor.getBlockEntity() instanceof ModularRouterBlockEntity) {
            if (data.getBoolean("Denied")) {
                iTooltip.add(xlate("modularrouters.chatText.security.accessDenied"));
            } else {
                if (data.getInt("ModuleCount") > 0) {
                    List<Component> componentList = new ArrayList<>();
                    MiscUtil.appendMultilineText(componentList, ChatFormatting.WHITE, "modularrouters.itemText.misc.moduleCount", data.getInt("ModuleCount"));
                    iTooltip.addAll(componentList);
                }
                CompoundTag upgrades = data.getCompound("Upgrades");
                if (!upgrades.isEmpty()) {
                    iTooltip.add(xlate("modularrouters.itemText.misc.upgrades"));
                    for (String k : upgrades.getAllKeys()) {
                        iTooltip.add(xlate("modularrouters.itemText.misc.upgradeCount", upgrades.getInt(k), I18n.get(k)));
                    }
                }
                RouterRedstoneBehaviour rrb = RouterRedstoneBehaviour.values()[data.getInt("RedstoneMode")];
                iTooltip.add(xlate("modularrouters.guiText.tooltip.redstone.label")
                        .append(": " + ChatFormatting.AQUA)
                        .append(xlate("modularrouters.guiText.tooltip.redstone." + rrb))
                );
                if (data.getBoolean("EcoMode")) {
                    iTooltip.add(xlate("modularrouters.itemText.misc.ecoMode"));
                }
            }
        }
    }

