            ItemStack stack = ItemHandlerHelper.copyStackWithSize(stacks.get(pos), getItemsPerTick(router));
            pos++;
            ItemStack inserted = router.insertBuffer(stack);
            if (inserted.getCount() < stack.getCount()) {
                return true;
            }
        }
        return false;
    }

