@Override
    public boolean matchItem(ItemStack stack, Filter.Flags flags) {
        int matched = 0;
        if (comparisonList.items.isEmpty()) {
            return false;
        }
        for (Comparison comp : comparisonList.items) {
            if (comp.test(stack)) {
                if (!comparisonList.matchAll) {
                    return true;
                } else {
                    matched++;
                }
            }
        }
        return matched >= comparisonList.items.size();
    }

