public RegexMatcher(List<String> regex) {
        patterns = Lists.newArrayListWithCapacity(regex.size());

        for (String r : regex) {
            try {
                // TODO case sensitivity configurable?
                Pattern pat = Pattern.compile(r, Pattern.CASE_INSENSITIVE);
                patterns.add(pat);
            } catch (PatternSyntaxException e) {
                ModularRouters.LOGGER.warn("can't compile '" + r + "' - " + e.getMessage());
            }
        }
    }

@Override
    public boolean matchItem(ItemStack stack, Filter.Flags flags) {
        if (stack.isEmpty()) return false;
        String name = MiscUtil.getRegistryName(stack.getItem()).orElseThrow().getPath();
        return patterns.stream().anyMatch(pat -> pat.matcher(name).find());
    }

public SimpleItemMatcher(ItemStack stack) {
        Validate.isTrue(!stack.isEmpty());
        this.filterStack = stack;
    }

@Override
    public boolean matchItem(ItemStack stack, Filter.Flags flags) {
        if (filterStack.getItem() == stack.getItem()) {
            return (flags.isIgnoreDamage() || matchDamage(stack, filterStack))
                    && (flags.isIgnoreNBT() || ItemStack.isSameItemSameTags(stack, filterStack));
        } else if (flags.matchTags()) {
            return getTagMatcher().match(stack);
        } else {
            return false;
        }
    }

private ItemTagMatcher getTagMatcher() {
        if (tagMatcher == null) tagMatcher = new ItemTagMatcher(filterStack);
        return tagMatcher;
    }

private boolean matchDamage(ItemStack stack1, ItemStack stack2) {
        // items are already checked to be the same, only interested in durability here
        return !stack1.isDamageableItem() || stack1.getDamageValue() == stack2.getDamageValue();
    }

public TagMatcher(Collection<TagKey<Item>> tagList) {
        this.tagList = tagList;
    }

@Override
    public boolean matchItem(ItemStack stack, Filter.Flags flags) {
        return tagList.stream().anyMatch(stack::is);
    }

